package pzvrphysicality;
import java.io.*;import java.nio.file.*;import java.util.*;import viewpoint.core.Frame;import zombie.iso.*;import zombie.iso.objects.*;import zombie.core.skinnedmodel.model.*;import zombie.core.skinnedmodel.model.jassimp.*;
/** Original closed versus overhead mesh, same native owner and exact provider pose. */
public final class BasileGarageOpeningTest {
 private static int checks;private static void check(boolean v,String why){if(!v)throw new AssertionError(why);checks++;}
 private static ProcessedAiScene read(Path data)throws Exception{try(var in=new DataInputStream(Files.newInputStream(data))){int v=in.readInt(),n=in.readInt();var a=new VertexBufferObject.VertexArray(v);float[] p=new float[v*3];int[] f=new int[n];for(int i=0;i<p.length;i++)p[i]=in.readFloat();for(int i=0;i<n;i++)f[i]=in.readInt();for(int i=0;i<v;i++)for(int c=0;c<4;c++)a.data[i][1][c]=in.readFloat();for(int i=0;i<v;i++)for(int c=0;c<4;c++)a.data[i][2][c]=in.readInt();for(int i=0;i<v;i++)for(int c=0;c<3;c++)a.data[i][0][c]=p[i*3+c];if(in.read()!=-1)throw new AssertionError("private fixture extent");return new ProcessedAiScene(new ImportedSkinnedMesh(a,f));}}
 private static void offer(IsoDoor d,Frame f,ModelMesh mesh,SpriteModel model){f.scene.models.clear();f.scene.models.skin(DoorMeshCpuTest.identity(),1);f.drawers.clear();f.drawers.add(new IsoObjectModelDrawer(model,mesh));NativeDoorCapture.begin(f,d,0);f.scene.models.add(mesh,new org.joml.Matrix4f().translation(9.5f,.2f,9.5f).rotateY((float)(Math.PI/2)).scale(2f/3).get(new float[16]),0);NativeDoorCapture.end(f,d,true);}
 public static void main(String[] args)throws Exception{
  String closed="garage_white_garage_w_0_closed",open="garage_white_garage_w_0_open";Path media=Path.of(args[3]).resolve("opening-provider/mods/BasileDoors3D/42/media");Files.createDirectories(media.resolve("java/client"));Files.createDirectories(media.resolve("models_X/BasileDoors3D"));Path jar=media.resolve("java/client/BasileDoors3D.jar");Files.copy(Path.of(args[0]),jar);Path original=Path.of(args[0]).getParent().getParent().getParent().resolve("models_X/BasileDoors3D");for(String key:List.of(closed,open))Files.copy(original.resolve(key+".glb"),media.resolve("models_X/BasileDoors3D/"+key+".glb"));var selected=BasileDoorAssets.verify(jar,basile.doors3d.DoorModels.class,basile.doors3d.DoorCatalog.class);var sf=BasileDoorAssets.class.getDeclaredField("selected");sf.setAccessible(true);sf.set(null,selected);zombie.ZomboidFileSystem.root=selected.root;
  var a=new ModelMesh("BasileDoors3D/"+closed);a.skinningData=new SkinningData();DoorMeshCpu.capture(read(Path.of(args[1])),a);var b=new ModelMesh("BasileDoors3D/"+open);b.skinningData=new SkinningData();DoorMeshCpu.capture(read(Path.of(args[2])),b);check(DoorMeshCpu.get(a)!=null&&DoorMeshCpu.get(b)!=null,"both distinct published garage assets verified before same-owner capture");
  var p=NativeDoorCaptureTest.player();var d=NativeDoorCaptureTest.door(p);d.spriteModel=null;d.spriteModelInit=d.sprite;IsoObjectAnimations.reset();WorldContactCapture.requestItems(true);WorldContactCapture.scope(p);NativeDoorCapture.clear();var frame=new Frame();var model=new SpriteModel();model.scale=2f/3;model.translate.set(-.45f,0,-.5f);model.rotate.set(0,90,0);model.animation="Open";model.texture="BasileDoors3D/special";model.runtime="standard_door w closed";model.name="BasileDoors3D."+closed;d.sprite.name="industry_trucks_01_32";basile.doors3d.DoorModels.bind(d,model);basile.doors3d.DoorCatalog.set(d.sprite.name,new basile.doors3d.DoorCatalog.Entry(model.name,model.texture,true,false,new basile.doors3d.DoorCatalog.Pose(-.45f,0,-.5f,0,90,0,2f/3,0,"Open"),null,null,"w"));offer(d,frame,a,model);var rows=NativeDoorCapture.sample(p);check(rows.size()==1,"exact closed garage render establishes real triangles");var before=rows.getFirst().shape();float[] v=before.vertices();double[] lo={Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY},hi={-Double.POSITIVE_INFINITY,-Double.POSITIVE_INFINITY,-Double.POSITIVE_INFINITY};for(int i=0;i<v.length;i++) {lo[i%3]=Math.min(lo[i%3],v[i]);hi[i%3]=Math.max(hi[i%3],v[i]);}int normal=hi[0]-lo[0]<hi[1]-lo[1]?0:1;double[] from={(lo[0]+hi[0])/2,(lo[1]+hi[1])/2,(lo[2]+hi[2])/2},to=from.clone();from[normal]=lo[normal]-.1;to[normal]=hi[normal]+.1;check(NativeWindowGeometry.intersects(before,from[0],from[1],from[2],to[0],to[1],to[2]),"closed original opaque panel blocks its central doorway segment");
  d.open=true;check(NativeDoorCapture.sample(p).isEmpty(),"native transition immediately revokes old closed panel");d.sprite.name="industry_trucks_01_40";model.name="BasileDoors3D."+open;model.runtime="standard_door w open";basile.doors3d.DoorCatalog.set(d.sprite.name,new basile.doors3d.DoorCatalog.Entry(model.name,model.texture,true,true,new basile.doors3d.DoorCatalog.Pose(-.45f,0,-.5f,0,90,0,2f/3,0,"Open"),null,null,"w"));offer(d,frame,b,model);rows=NativeDoorCapture.sample(p);check(rows.size()==1&&rows.getFirst().shape()!=before,"new exact overhead mesh replaces closed geometry for the same native owner");check(!NativeWindowGeometry.intersects(rows.getFirst().shape(),from[0],from[1],from[2],to[0],to[1],to[2]),"actual open overhead geometry leaves the central doorway clear without a proxy wall");check(NativeDoorCapture.owns(d),"open native producer retains packed duplicate suppression");check(d.spriteModel==null&&IsoObject.lazyCalls==0&&IsoObjectAnimations.builds==0,"missing raw cache remains untouched and no factory executed");System.out.println("Basile garage opening: "+checks+" checks passed");
 }
}
